import React from 'react';
// Import the new NavRight component
import { NavContainer, NavLogo, NavRight, NavLinks, NavLink, SocialLinks, SocialIcon } from './Navbar.styles';
import { GitHubIcon, LinkedInIcon, EmailIcon } from './Icons';

const Navbar = () => {
  return (
    <NavContainer>
      <NavLogo href="/">YA</NavLogo> {/* Your Initials */}
      <NavRight>
        <NavLinks>
          <NavLink href="#home">Home</NavLink>
          <NavLink href="#projects">Projects</NavLink>
        </NavLinks>
        <SocialLinks>
          <SocialIcon href="https://github.com" target="_blank" rel="noopener noreferrer"><GitHubIcon /></SocialIcon>
          <SocialIcon href="https://linkedin.com" target="_blank" rel="noopener noreferrer"><LinkedInIcon /></SocialIcon>
          <SocialIcon href="mailto:your.email@example.com"><EmailIcon /></SocialIcon>
        </SocialLinks>
      </NavRight>
    </NavContainer>
  );
};

export default Navbar;
